'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var Complex128Array = require( '@stdlib/array/complex128' );
var Float64Array = require( '@stdlib/array/float64' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var add5 = require( '@stdlib/number/float64/base/add5' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var quinary = require( './../lib' );


// FUNCTIONS //

/**
* Computes the sum of five double-precision complex floating-point numbers.
*
* @private
* @param {Complex128} z1 - first complex number
* @param {Complex128} z2 - second complex number
* @param {Complex128} z3 - third complex number
* @param {Complex128} z4 - fourth complex number
* @param {Complex128} z5 - fourth complex number
* @returns {Complex128} result
*/
function zadd5( z1, z2, z3, z4, z5 ) {
	var re = real( z1 ) + real( z2 ) + real( z3 ) + real( z4 ) + real( z5 );
	var im = imag( z1 ) + imag( z2 ) + imag( z3 ) + imag( z4 ) + imag( z5 );
	return new Complex128( re, im );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof quinary, 'function', 'main export is a function');
	t.end();
});

tape( 'the function applies a quinary callback to indexed elements of three 0-dimensional ndarrays', function test( t ) {
	var expected;
	var x;
	var y;
	var z;
	var w;
	var u;
	var v;

	x = scalar2ndarray( 5.0, {
		'dtype': 'float64'
	});

	y = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});

	z = scalar2ndarray( 3.0, {
		'dtype': 'float64'
	});

	w = scalar2ndarray( 2.0, {
		'dtype': 'float64'
	});

	u = scalar2ndarray( 1.0, {
		'dtype': 'float64'
	});

	v = scalar2ndarray( 0.0, {
		'dtype': 'float64'
	});

	quinary( [ x, y, z, w, u, v ], add5 );

	expected = new Float64Array( [ 15.0 ] );
	t.strictEqual( isSameFloat64Array( getData( v ), expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function applies a quinary callback to indexed elements of three 0-dimensional ndarrays (accessors)', function test( t ) {
	var expected;
	var x;
	var y;
	var z;
	var w;
	var u;
	var v;

	x = scalar2ndarray( new Complex128( 5.0, 5.0 ), {
		'dtype': 'complex128'
	});

	y = scalar2ndarray( new Complex128( 4.0, 4.0 ), {
		'dtype': 'complex128'
	});

	z = scalar2ndarray( new Complex128( 3.0, 3.0 ), {
		'dtype': 'complex128'
	});

	w = scalar2ndarray( new Complex128( 2.0, 2.0 ), {
		'dtype': 'complex128'
	});

	u = scalar2ndarray( new Complex128( 1.0, 1.0 ), {
		'dtype': 'complex128'
	});

	v = scalar2ndarray( new Complex128( 0.0, 0.0 ), {
		'dtype': 'complex128'
	});

	quinary( [ x, y, z, w, u, v ], zadd5 );

	expected = new Complex128Array( [ 15.0, 15.0 ] );
	t.strictEqual( isSameComplex128Array( getData( v ), expected ), true, 'returns expected value' );
	t.end();
});
